<?php $item = $item ?? []; $isEdit = !empty($item['id']); ?>
<section class="mx-auto max-w-7xl"><header class="cms-header slide-in"><div><p class="eyebrow">Admin CMS</p><h1 class="section-title mt-3"><?= $isEdit ? 'Edit Photo' : 'Add Photo' ?></h1><p class="mt-4 max-w-2xl text-base leading-7 text-neutral-600">Galeri foto tersimpan langsung ke backend.</p></div><a href="/admin/photo" class="btn btn-secondary">View All</a></header><form class="editor-workspace compact mt-6" id="photo-form" data-ssr="true" data-photo-id="<?= (int) ($item['id'] ?? 0) ?>"><main class="block-writing-surface"><div class="admin-upload-zone"><p class="font-bold text-neutral-950">Upload Photo</p><div id="photo-preview" class="config-preview mb-3"><?php if (!empty($item['image'])): ?><img src="<?= $e($item['image']) ?>" alt="<?= $e($item['title'] ?? 'Photo preview') ?>"><?php else: ?><div class="config-empty">Belum ada foto</div><?php endif; ?></div><input id="photo-file" class="admin-file-input" type="file" accept="image/*"><p class="text-sm text-neutral-600">JPG, PNG, GIF, dan WebP hingga 5MB.</p></div></main><aside class="editor-config-sidebar"><section class="config-card"><h2>Photo Info</h2><label class="config-field"><span>Title</span><input id="photo-title" class="config-input" value="<?= $e($item['title'] ?? '') ?>" required></label><label class="config-field"><span>Image URL</span><input id="photo-image" class="config-input" value="<?= $e($item['image'] ?? '') ?>" required></label><label class="config-field"><span>Caption</span><input id="photo-caption" class="config-input" value="<?= $e($item['caption'] ?? '') ?>"></label><label class="config-field"><span>Visibility</span><select id="photo-visibility" class="config-input js-admin-custom-select"><option value="show" <?= ($item['status'] ?? 'show') === 'show' ? 'selected' : '' ?>>Show</option><option value="hide" <?= ($item['status'] ?? '') === 'hide' ? 'selected' : '' ?>>Hide</option></select></label></section><button type="submit" class="btn btn-primary w-full">Submit Photo</button></aside></form></section>
